class _ArchWalk(LocalCommand[ArchWalk, ArchWalked, ArchWalked]):
    """``cad.arch.walk`` v1. Dolaşım güzergâhı: Tek katta başlangıç ve bitiş arasında
    seçilen geçiş genişliğini koruyan güzergâhı arar. Net mahal sınırlarını, kapı
    netlerini, kolonları ve donatıları okur. shellOnly yalnız sabit plan sınırlarını ve
    kolonları alır. Sonuç geçici tasarım ölçümüdür. Çizimi değiştirmez.
    """
    __slots__ = ()
    id = "cad.arch.walk"
    version = 1
    title = "Dolaşım güzergâhı"
    scope = "document"
    input_type = ArchWalk
    output_type = ArchWalked
    plan_type = ArchWalked

    def __call__(
        self,
        doc: Document,
        /,
        *,
        start: Vec2Like,
        end: Vec2Like,
        width: float,
        level: str | None | Unset = UNSET,
        shell_only: bool | Unset = UNSET,
        request_id: str | None = None,
        expected: Expected | None = None,
    ) -> ArchWalked:
        """Dolaşım güzergâhı: Tek katta başlangıç ve bitiş arasında seçilen geçiş genişliğini
        koruyan güzergâhı arar. Net mahal sınırlarını, kapı netlerini, kolonları ve
        donatıları okur. shellOnly yalnız sabit plan sınırlarını ve kolonları alır. Sonuç
        geçici tasarım ölçümüdür. Çizimi değiştirmez.

        Args:
            doc: The drawing it works on.
            start: Unit: length.
            end: Unit: length.
            width: Unit: length.
            level:
            shell_only: Exclude movable furniture and equipment when inspecting the architectural shell.
            request_id: Names this write: sent again with the same call it is answered as
                before and applied once (docs/adr/0253 §6).
            expected: What must still hold (:class:`Expected`: the revision, stamps, a plan's
                id); otherwise nothing is written and RevisionConflict is raised.

        Returns:
            ArchWalked

        Raises:
            CommandFailed, NeedsInput, RevisionConflict: the command's refusal;
                nothing was written. Warnings go to :mod:`warnings` as CommandWarning.
        """
        return self.execute_input(doc, ArchWalk(
            start=Vec2.of(start),
            end=Vec2.of(end),
            width=width,
            level=level,
            shell_only=shell_only,
        ), request_id=request_id, expected=expected)

    def plan(
        self,
        doc: Document,
        /,
        *,
        start: Vec2Like,
        end: Vec2Like,
        width: float,
        level: str | None | Unset = UNSET,
        shell_only: bool | Unset = UNSET,
    ) -> ArchWalked:
        """What it would write, with nothing written; the plan's ``revision``, given as
        ``expected_revision``, writes exactly this plan or nothing.
        """
        return self.plan_input(doc, ArchWalk(
            start=Vec2.of(start),
            end=Vec2.of(end),
            width=width,
            level=level,
            shell_only=shell_only,
        ))

    def validate(
        self,
        doc: Document,
        /,
        *,
        start: Vec2Like,
        end: Vec2Like,
        width: float,
        level: str | None | Unset = UNSET,
        shell_only: bool | Unset = UNSET,
    ) -> list[CommandNote]:
        """Checks the input against the drawing, writing nothing; its warnings.
        A refusal raises as for the call.
        """
        return self.validate_input(doc, ArchWalk(
            start=Vec2.of(start),
            end=Vec2.of(end),
            width=width,
            level=level,
            shell_only=shell_only,
        ))

    def answer(
        self,
        doc: Document,
        /,
        *,
        start: Vec2Like,
        end: Vec2Like,
        width: float,
        level: str | None | Unset = UNSET,
        shell_only: bool | Unset = UNSET,
        op: str = "execute",
        request_id: str | None = None,
        expected: Expected | None = None,
    ) -> Outcome[Any]:
        """``op`` (``execute``, ``plan`` or ``validate``) by the protocol (docs/adr/0253):
        the whole answer, a refusal in it rather than raised, with what it touched
        (``summary``), the plan's id (``plan_id``), whether the request was answered
        before (``replayed``) and its journal row (``call``).
        """
        return self.answer_input(doc, ArchWalk(
            start=Vec2.of(start),
            end=Vec2.of(end),
            width=width,
            level=level,
            shell_only=shell_only,
        ), op=op, request_id=request_id, expected=expected)


